/**
 * Organization rows plus slug uniqueness and slug retirement.
 *
 * A workspace's current slug is `organizations.slug`. A slug it renames away from
 * is kept in `organization_retired_slugs` for `ORG_SLUG_HOLD_DAYS` (ADR 0005), and
 * every lookup by slug treats such a slug as belonging to that workspace.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import {
  getDb,
  members,
  organizationRetiredSlugs,
  organizations,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * The live workspace a slug resolves to: the one whose current slug it is, or
 * the one that retired it and still holds it. The session layer, the service
 * layer and the route layouts all resolve slugs through here.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = findHeldRetirement(slug, Date.now());
  if (retired === null) return null;

  const owner = getDb()
    .select()
    .from(organizations)
    .where(
      and(
        eq(organizations.id, retired.orgId),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return owner ? toOrganization(owner) : null;
}

/** Whether a slug retired at `retiredAt` is still held at `now` (epoch ms). */
function isHeld(retiredAt: string, now: number): boolean {
  return new Date(retiredAt).getTime() + ORG_SLUG_HOLD_DAYS * MS_PER_DAY > now;
}

/** The retirement row for `slug`, if that retirement still holds at `now`. */
function findHeldRetirement(slug: string, now: number) {
  const row = getDb()
    .select()
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .get();
  return row && isHeld(row.retiredAt, now) ? row : null;
}

/**
 * Whether `slug` may become `orgId`'s current slug (ADR 0005, rule 2). It is
 * refused while any other workspace, live or deleted, holds it, and while
 * another workspace holds it retired. A slug `orgId` retired itself is
 * available to it.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const holder = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (holder && holder.id !== orgId) return false;

  const retired = findHeldRetirement(slug, Date.now());
  return retired === null || retired.orgId === orgId;
}

/**
 * Moves `orgId` from `from` to `to` and retires `from`, in one transaction.
 * Taking `to` ends any retirement it had: either the workspace's own, which it
 * takes back, or one whose hold has lapsed. The caller checks availability
 * first, so a refused rename never reaches this function.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  from: string,
  to: string,
): Promise<Organization> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, to))
      .run();

    tx.insert(organizationRetiredSlugs)
      .values({ slug: from, orgId, retiredAt: stamp })
      .onConflictDoUpdate({
        target: organizationRetiredSlugs.slug,
        set: { orgId, retiredAt: stamp },
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug: to, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    if (!row) throw new Error(`Organization ${orgId} not found`);
    return toOrganization(row);
  });
}

