/**
 * Changes the workspace's URL slug (ADR 0005). The old slug is retired for
 * `ORG_SLUG_HOLD_DAYS`, during which it keeps resolving to this workspace. The
 * new slug is taken exactly as typed: a slug that is not available is refused,
 * never suffixed. Renaming to the current slug changes nothing and publishes
 * nothing. A refusal writes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  const current = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  if (current.slug === input.slug) return current;

  if (!(await orgRepo.isOrgSlugAvailable(input.slug, input.orgId))) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const renamed = await orgRepo.renameOrgSlug(
    input.orgId,
    current.slug,
    input.slug,
  );

  await record(input.orgId, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: renamed.id,
    projectId: null,
    summary: `Workspace URL changed from ${current.slug} to ${renamed.slug}`,
    metadata: { from: current.slug, to: renamed.slug },
  });

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: current.slug,
    to: renamed.slug,
  });

  return renamed;
}

