input.content:
/**
 * Workspace URL renames, against a real database (ADR 0005).
 *
 * A retired slug keeps resolving to its workspace for `ORG_SLUG_HOLD_DAYS`,
 * then is released. A taken or held slug is refused, never suffixed. A rename
 * to the current slug is a no-op. A successful rename publishes one event and
 * writes one audit row, both naming the two slugs.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let counter = 0;
const detachers: Unsubscribe[] = [];

/** A workspace with a unique slug, so each case owns its own URLs. */
async function freshTenant(): Promise<Tenant> {
  counter += 1;
  return createTenant(`ws${counter}`);
}

/** Records every `organization.slug_changed` delivered during a test. */
function captureRenames() {
  const seen: { orgId: string; actorId: string | null; from: string; to: string }[] = [];
  detachers.push(
    subscribe("organization.slug_changed", (payload) => {
      seen.push({
        orgId: payload.orgId,
        actorId: payload.actorId,
        from: payload.from,
        to: payload.to,
      });
    }),
  );
  return seen;
}

async function resolvesTo(slug: string): Promise<string | null> {
  return (await orgRepo.findOrgBySlug(slug))?.id ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("renameOrganizationSlug", () => {
  it("makes the new slug current and keeps the old one resolving", async () => {
    const t = await freshTenant();
    const next = `${t.org.slug}-renamed`;

    const renamed = await orgService.renameOrganizationSlug(t.actors.owner, {
      orgId: t.org.id,
      slug: next,
    });

    expect(renamed.slug).toBe(next);
    expect((await orgRepo.findOrgById(t.org.id))?.slug).toBe(next);
    expect(await resolvesTo(next)).toBe(t.org.id);
    expect(await resolvesTo(t.org.slug)).toBe(t.org.id);
  });

  it("releases the old slug exactly ORG_SLUG_HOLD_DAYS after the rename", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    const start = new Date("2026-03-01T00:00:00.000Z").getTime();
    vi.setSystemTime(start);

    const t = await freshTenant();
    await orgService.renameOrganizationSlug(t.actors.owner, {
      orgId: t.org.id,
      slug: `${t.org.slug}-held`,
    });

    const holdEnd = start + ORG_SLUG_HOLD_DAYS * DAY_MS;
    vi.setSystemTime(holdEnd - 1);
    expect(await resolvesTo(t.org.slug)).toBe(t.org.id);

    vi.setSystemTime(holdEnd);
    expect(await resolvesTo(t.org.slug)).toBeNull();
  });

  it("refuses a slug another workspace holds, live or retired, and changes nothing", async () => {
    const a = await freshTenant();
    const b = await freshTenant();
    const bRenamed = `${b.org.slug}-moved`;
    await orgService.renameOrganizationSlug(b.actors.owner, {
      orgId: b.org.id,
      slug: bRenamed,
    });
    const renames = captureRenames();

    // `b.org.slug` is now retired and held by `b`; `bRenamed` is live on `b`.
    await expect(
      orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: b.org.slug }),
    ).rejects.toThrow(InvalidSlugError);
    await expect(
      orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: bRenamed }),
    ).rejects.toThrow(InvalidSlugError);

    expect((await orgRepo.findOrgById(a.org.id))?.slug).toBe(a.org.slug);
    expect(await resolvesTo(b.org.slug)).toBe(b.org.id);
    expect(renames).toHaveLength(0);
  });

  it("lets a workspace take back a slug it retired, and retires the one it replaces", async () => {
    const t = await freshTenant();
    const first = t.org.slug;
    const second = `${first}-two`;
    const third = `${first}-three`;

    await orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: second });
    await orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: third });

    // Every earlier slug keeps its own hold.
    expect(await resolvesTo(first)).toBe(t.org.id);
    expect(await resolvesTo(second)).toBe(t.org.id);

    // Taking `first` back ends its retirement and retires `third`.
    await orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: first });
    expect((await orgRepo.findOrgById(t.org.id))?.slug).toBe(first);
    expect(await resolvesTo(third)).toBe(t.org.id);
    expect(await resolvesTo(first)).toBe(t.org.id);
  });

  it("makes creation derive around a slug that is still held", async () => {
    const t = await freshTenant();
    await orgService.renameOrganizationSlug(t.actors.owner, {
      orgId: t.org.id,
      slug: `${t.org.slug}-now`,
    });

    const created = await orgService.createOrganization(t.userIds.owner, {
      name: "Successor",
      slug: t.org.slug,
      plan: "free",
    });

    expect(created.slug).toBe(`${t.org.slug}-2`);
  });

  it("treats renaming to the current slug as a no-op with no event and no audit row", async () => {
    const t = await freshTenant();
    const renames = captureRenames();

    const same = await orgService.renameOrganizationSlug(t.actors.owner, {
      orgId: t.org.id,
      slug: t.org.slug,
    });

    expect(same.slug).toBe(t.org.slug);
    expect(renames).toHaveLength(0);
    const audit = await activityRepo.listActivity({
      orgId: t.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(0);
  });

  it("publishes one event and writes one audit row naming both slugs, for the actor", async () => {
    const t = await freshTenant();
    const next = `${t.org.slug}-audited`;
    const renames = captureRenames();

    await orgService.renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: next });

    expect(renames).toEqual([
      { orgId: t.org.id, actorId: t.userIds.admin, from: t.org.slug, to: next },
    ]);
    const audit = await activityRepo.listActivity({
      orgId: t.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      actorId: t.userIds.admin,
      subjectKind: "organization",
      subjectId: t.org.id,
      metadata: { from: t.org.slug, to: next },
    });
  });

  it("refuses a member who may not change workspace settings, and changes nothing", async () => {
    const t = await freshTenant();

    await expect(
      orgService.renameOrganizationSlug(t.actors.member, {
        orgId: t.org.id,
        slug: `${t.org.slug}-nope`,
      }),
    ).rejects.toThrow();

    expect((await orgRepo.findOrgById(t.org.id))?.slug).toBe(t.org.slug);
  });
});

